MAP
    NAME "primerMapa"
    SIZE 800 500
    STATUS ON
    IMAGETYPE "png24"
    TRANSPARENT OFF
    EXTENT 1053867 860190 1068491 879441
    SHAPEPATH "C:/ms4w/Apache/htdocs/Geomovilidad/shapeCali41/"
    FONTSET "C:/ms4w/Apache/htdocs/Geomovilidad/misc/fonts/fonts.txt"

    IMAGECOLOR 25 118 210

    OUTPUTFORMAT
        NAME "png24"
        DRIVER AGG/PNG
        MIMETYPE "image/png"
        IMAGEMODE RGBA
        EXTENSION "png"
    END



    WEB
        IMAGEPATH "C:/ms4w/tmp/ms_tmp/"
        IMAGEURL "/ms_tmp/"
    END

    SYMBOL
        NAME "ubicacion_icono"
        TYPE PIXMAP
        IMAGE "C:/ms4w/Apache/htdocs/Geomovilidad/view/assets/img/ubicacionreportes.png"
    END

    LAYER
        NAME "cali_area"
        TYPE POLYGON
        STATUS ON
        DATA "CaliArea.shp"

        CLASS
            STYLE
                COLOR 67 160 71
                OUTLINECOLOR 0 0 0
            END
        END
    END

    LAYER
        NAME "comunas"
        STATUS ON
        TYPE LINE
        DATA "ComunasC.shp"

        CLASS
            STYLE
                COLOR 251 140 0
                OUTLINECOLOR 100 100 255
            END
        END
    END

    LAYER
        NAME "vias"
        STATUS ON
        TYPE LINE
        DATA "MallaVialC.shp"

        LABELITEM "nombre"
        CLASS
            NAME "LABEL"
            STYLE
                COLOR 142 36 170
                WIDTH 2
            END
            LABEL
                TYPE TRUETYPE
                FONT "sans"
                SIZE 8
                COLOR 0 0 0
                MINDISTANCE 100
                PARTIALS FALSE
            END
        END
    END

    LAYER
        NAME "barrios"
        TYPE POLYGON
        STATUS ON
        TRANSPARENCY 45
        DATA "Barrios.shp"

        LABELITEM "BARRIO"
        CLASS
            NAME "LABEL"
            STYLE
                COLOR 166 225 250
                OUTLINECOLOR 90 40 35
            END
            LABEL
                TYPE BITMAP
                SIZE LARGE
                COLOR 0 0 0
                MINDISTANCE 150
                PARTIALS FALSE
            END
        END
    END

  
    # CAPAS POSTGIS - Solicitudes


    # 1) Reportes de accidentes (ya tiene geometría nativa)
    LAYER
        NAME "reportes_accidentes"
        CONNECTIONTYPE postgis
        STATUS ON
        CONNECTION "user=postgres password=1234 dbname=Geomovilidad host=localhost port=5433"
        DATA "geom FROM (
            SELECT sra_id,
                   ST_SetSRID(sra_coordenadas, 0) AS geom,
                   sra_descripcion,
                   sra_fecha
            FROM solicitudes_reporte_accidentes
            WHERE sra_coordenadas IS NOT NULL
        ) AS sub USING UNIQUE sra_id USING SRID=0"
        TYPE POINT

        CLASS
            STYLE
                SYMBOL "ubicacion_icono"
                SIZE 26
            END
        END
    END

    # 2) Solicitudes de vía en mal estado (x,y sueltos -> construir el punto)
    LAYER
        NAME "vias_mal_estado"
        CONNECTIONTYPE postgis
        STATUS ON
        CONNECTION "user=postgres password=1234 dbname=Geomovilidad host=localhost port=5433"
        DATA "geom FROM (
            SELECT svme_id,
                   ST_SetSRID(ST_MakePoint(svme_coord_x, svme_coord_y), 0) AS geom,
                   svme_descripcion_detallada
            FROM solicitudes_via_mal_estado
            WHERE svme_coord_x IS NOT NULL AND svme_coord_y IS NOT NULL
        ) AS sub USING UNIQUE svme_id USING SRID=0"
        TYPE POINT

        CLASS
            STYLE
                SYMBOL "ubicacion_icono"
                SIZE 26
            END
        END
    END

    # 3) Solicitudes de nueva señal
    LAYER
        NAME "nueva_senal"
