            FROM solicitudes_nueva_senal
            WHERE sns_coord_x IS NOT NULL AND sns_coord_y IS NOT NULL
        ) AS sub USING UNIQUE sns_id USING SRID=0"
        TYPE POINT

        CLASS
            STYLE
                SYMBOL "ubicacion_icono"
                SIZE 26
            END
        END
    END

