        END
    END

    # 5) Reportes de reductor en mal estado
    LAYER
        NAME "reductor_mal_estado"
        CONNECTIONTYPE postgis
        STATUS ON
        CONNECTION "user=postgres password=1234 dbname=Geomovilidad host=localhost port=5433"
